class Solution:

	def bTreeToClist(self, root):
		a = [None]
		b = [None]
		num = root

		def link(num):
			if num == None:
				return num
			link(num.left)
			if b[0] == None:
				a[0] = b[0] = num
			else:
				b[0].right = num
				num.left = b[0]
			b[0] = num
			link(num.right)
		link(num)
		a[0].left = b[0]
		b[0].right = a[0]
		return a[0]
